package org.telegram.messenger; import java.util.*; import android.content.SharedPreferences; public class MessagesController { public static class Prefs implements SharedPreferences,SharedPreferences.Editor { public Map<String,Object> data=new HashMap<>(); public String getString(String k,String d){return (String)data.getOrDefault(k,d);} public int getInt(String k,int d){return (Integer)data.getOrDefault(k,d);} public long getLong(String k,long d){return (Long)data.getOrDefault(k,d);} public boolean getBoolean(String k,boolean d){return (Boolean)data.getOrDefault(k,d);} public Editor edit(){return this;} public Editor putString(String k,String v){data.put(k,v); return this;} public Editor putInt(String k,int v){data.put(k,v);return this;} public Editor putLong(String k,long v){data.put(k,v);return this;} public Editor putBoolean(String k,boolean v){data.put(k,v);return this;} public void apply(){} public boolean commit(){return true;} } public static final Prefs prefs = new Prefs(); public static SharedPreferences getGlobalMainSettings(){return prefs;} }